import os
import numpy as np

# ==========================================
# 1. File System Configuration
# ==========================================

# Base Directories
BASE_DIR = os.getcwd()
INPUT_DIR = os.path.join(BASE_DIR, "input")
METADATA_DIR = os.path.join(BASE_DIR, "metadata")
WORKING_DIR = os.path.join(BASE_DIR, "working")
SUBMISSION_DIR = os.path.join(BASE_DIR, "submission")

# Specific Data Paths (Metadata)
# These files are generated by the metadata script and contain train/val splits
TRAIN_META_PATH = os.path.join(METADATA_DIR, "train.csv")
VAL_META_PATH = os.path.join(METADATA_DIR, "val.csv")
TEST_META_PATH = os.path.join(METADATA_DIR, "test.csv")

# Raw Data Paths
IMAGES_DIR = os.path.join(INPUT_DIR, "images")
SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

# Output Paths
# Using idea_67 as the specific iteration identifier for caching
CACHE_DIR = os.path.join(WORKING_DIR, "idea_67")
SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

# Ensure necessary writable directories exist immediately upon import
os.makedirs(CACHE_DIR, exist_ok=True)
os.makedirs(SUBMISSION_DIR, exist_ok=True)

# ==========================================
# 2. Global Parameters & Hyperparameters
# ==========================================

# Reproducibility
RANDOM_SEED = 42

# Compute Resources
N_JOBS = 12

# Numerical Precision
# Explicitly using float64 for high-precision linear algebra operations
FLOAT_PRECISION = np.float64

# Dataset Control
# Set to None to use the full dataset. Set to an integer (e.g., 100) for debugging/fast runs.
DEBUG_SAMPLE_SIZE = None

# ==========================================
# 3. Feature Configuration
# ==========================================

# Pre-extracted tabular feature groups provided in the dataset
TABULAR_FEATURE_PREFIXES = ["margin", "shape", "texture"]

# Custom extracted geometric features (Axis-Augmented Geometric Fusion)
# The order here is strictly enforced for consistency between extraction and inference
GEOMETRIC_FEATURES = [
    "area",  # Absolute Mass: Integral size
    "major_axis_length",  # Absolute Length: Orthogonal to Area (via fitEllipse)
    "eccentricity",  # Elongation
    "solidity",  # Roughness (Area / ConvexArea)
    "extent",  # Rectangularity (Area / BoundingArea)
    "aspect_ratio",  # Orientation (BoundingWidth / BoundingHeight)
]

# Expected counts
NUM_TABULAR_FEATURES = 192  # 64 * 3
NUM_GEOMETRIC_FEATURES = 6

# ==========================================
# 4. Model & Pipeline Configuration
# ==========================================

# Sanitization
# Threshold for VarianceThreshold to remove constant features before scaling
VARIANCE_THRESHOLD = 0.0

# Transformation Pipeline
APPLY_YEO_JOHNSON = True
APPLY_SCALING = True

# OAS Estimator Configuration
# We assume data is centered manually (residuals = X - mu) for geometric consistency
OAS_ASSUME_CENTERED = True

# Post-processing
# Epsilon for clipping probabilities to avoid log(0) in metric calculation
PROB_CLIP_EPSILON = 1e-15

# ==========================================
# 5. Utility Functions
# ==========================================


def get_full_image_path(image_id):
    """
    Constructs the absolute path for a given image ID.

    Args:
        image_id (int or str): The unique identifier of the image.

    Returns:
        str: The absolute file path to the image.
    """
    return os.path.join(IMAGES_DIR, f"{int(image_id)}.jpg")
